import type { CoreDocument, CoreModule, ParagraphInfo, RenderedPage, TextLine } from './types';

/**
 * Mock core used while `src/core-wasm/` has not been generated by wasm-pack.
 * Three A4 pages: a light-gray fill with a darker band whose position depends
 * on the page index so pages are distinguishable.
 */
export const MOCK_VERSION = 'mock-0.0.0';
export const MOCK_PAGE_COUNT = 3;
export const MOCK_PAGE_WIDTH = 595;
export const MOCK_PAGE_HEIGHT = 842;
export const MOCK_SENTENCE = 'هذا نصٌّ تجريبي من النواة الوهمية لتطبيق ورّاق.';

const FILL = 235;
const BAND = 170;

function mockError(code: string, message: string): Error {
  const error = new Error(`${code}: ${message}`) as Error & { code: string };
  error.code = code;
  return error;
}

function assertPage(index: number): void {
  if (!Number.isInteger(index) || index < 0 || index >= MOCK_PAGE_COUNT) {
    throw mockError('E_RENDER', `page index ${index} out of range`);
  }
}

/** Band occupies 6 % of the page height, starting lower on each page. */
export function mockBandRows(height: number, index: number): [start: number, end: number] {
  const start = Math.floor(height * (0.12 + index * 0.08));
  const end = Math.floor(height * (0.18 + index * 0.08));
  return [start, end];
}

function renderPage(index: number, scale: number): RenderedPage {
  assertPage(index);
  if (!(scale > 0) || !Number.isFinite(scale)) {
    throw mockError('E_RENDER', `invalid scale ${scale}`);
  }
  const width = Math.max(1, Math.round(MOCK_PAGE_WIDTH * scale));
  const height = Math.max(1, Math.round(MOCK_PAGE_HEIGHT * scale));
  const rgba = new Uint8Array(width * height * 4);
  rgba.fill(FILL);
  const [bandStart, bandEnd] = mockBandRows(height, index);
  for (let row = bandStart; row < bandEnd; row += 1) {
    rgba.fill(BAND, row * width * 4, (row + 1) * width * 4);
  }
  for (let i = 3; i < rgba.length; i += 4) rgba[i] = 255;
  return { width, height, rgba, free: () => undefined };
}

function textLines(index: number): TextLine[] {
  assertPage(index);
  const lineHeight = 18;
  const [bandStartRatio] = mockBandRows(1, index);
  const firstBaseline = Math.round(MOCK_PAGE_HEIGHT * bandStartRatio) + 60;
  return [0, 1, 2].map((line) => ({
    text: MOCK_SENTENCE,
    x: 60,
    y: firstBaseline + line * lineHeight * 1.6,
    width: MOCK_PAGE_WIDTH - 120,
    height: lineHeight,
    direction: 'rtl' as const,
    free: () => undefined,
  }));
}

/** Two paragraphs per page so Edit mode has something to hit-test against. */
export const MOCK_PARAGRAPHS_PER_PAGE = 2;

class MockDocument implements CoreDocument {
  /** Lines added through `add_text`, so a test can see what was asked for. */
  private readonly added: { index: number; x: number; y: number; size: number; text: string }[] = [];
  /** `page:paragraph` → replacement text, so the mock reflects committed edits. */
  private readonly edits = new Map<string, string>();
  private revision = 0;

  private paragraphText(index: number, para: number): string {
    return this.edits.get(`${index}:${para}`) ?? `${MOCK_SENTENCE} (${para + 1})`;
  }

  page_count(): number {
    return MOCK_PAGE_COUNT;
  }

  page_size(index: number): Float32Array {
    assertPage(index);
    return Float32Array.of(MOCK_PAGE_WIDTH, MOCK_PAGE_HEIGHT);
  }

  render_page(index: number, scale: number): RenderedPage {
    return renderPage(index, scale);
  }

  extract_text(index: number): string {
    return textLines(index)
      .map((line) => line.text)
      .join('\n');
  }

  text_lines(index: number): TextLine[] {
    return textLines(index);
  }

  search(_query: string): Uint32Array {
    return Uint32Array.of(0);
  }

  metadata(): string {
    return JSON.stringify({
      title: 'Mock document',
      author: 'Warraq mock core',
      producer: MOCK_VERSION,
      creator: MOCK_VERSION,
      pages: MOCK_PAGE_COUNT,
      encrypted: false,
    });
  }

  paragraphs(index: number): ParagraphInfo[] {
    assertPage(index);
    const [bandStartRatio] = mockBandRows(1, index);
    const top = Math.round(MOCK_PAGE_HEIGHT * bandStartRatio) + 40;
    return [0, 1].slice(0, MOCK_PARAGRAPHS_PER_PAGE).map((para) => ({
      index: para,
      text: this.paragraphText(index, para),
      x: 60,
      y: top + para * 120,
      width: MOCK_PAGE_WIDTH - 120,
      height: 90,
      direction: 'rtl' as const,
      alignment: 'justify' as const,
      font_size: 14,
      line_count: 3,
      free: () => undefined,
    }));
  }

  replace_paragraph(index: number, para: number, text: string, font: Uint8Array): string {
    assertPage(index);
    if (para < 0 || para >= MOCK_PARAGRAPHS_PER_PAGE) {
      throw mockError('E_NOT_FOUND', `paragraph ${para} is not on page ${index}`);
    }
    if (font.byteLength === 0) throw mockError('E_RENDER', 'no font supplied');
    this.edits.set(`${index}:${para}`, text);
    this.revision += 1;
    // The mock has no real font table, so it always reports a substitution.
    return JSON.stringify({ lines_drawn: text.length === 0 ? 0 : 3, font_substituted: true });
  }

  add_text(index: number, x: number, y: number, size: number, text: string, font: Uint8Array): void {
    assertPage(index);
    if (text.trim().length === 0) throw mockError('E_EDIT', 'there is no text to add');
    if (!(size > 0)) throw mockError('E_EDIT', `font size ${size} is not usable`);
    if (font.byteLength === 0) throw mockError('E_RENDER', 'no font supplied');
    this.added.push({ index, x, y, size, text });
    this.revision += 1;
  }

  save(): Uint8Array {
    return new TextEncoder().encode(`%PDF-1.7\n% warraq mock save r${this.revision}\n%%EOF\n`);
  }

  free(): void {
    /* nothing to release */
  }
}

export function createMockModule(): CoreModule {
  return {
    version: () => MOCK_VERSION,
    Document: {
      open(bytes: Uint8Array, _password?: string): CoreDocument {
        if (bytes.byteLength === 0) throw mockError('E_PARSE', 'empty input');
        return new MockDocument();
      },
    },
  };
}
